"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { GAP, paginationRange } from "./pagination-range";

export { GAP, paginationRange } from "./pagination-range";
export type { PageItem } from "./pagination-range";

export type PaginationProps = {
  /** Current page, 1-based. */
  page: number;
  /** Total number of pages. Values below 1 render nothing. */
  pageCount: number;
  onChange: (page: number) => void;
  /** Pages shown either side of the current one. */
  siblings?: number;
  /** Pages pinned at each end. */
  boundaries?: number;
  /** Hide the numbers and show only prev / next with a "3 / 12" readout. */
  compact?: boolean;
  ariaLabel?: string;
  className?: string;
};

/**
 * Page navigation.
 *
 * Renders as a `<nav>` wrapping a list, with the current page carrying
 * `aria-current="page"` — so a screen reader announces position without having
 * to infer it from styling, which is the whole difference between this and a
 * row of styled buttons.
 */
export function Pagination({
  page,
  pageCount,
  onChange,
  siblings = 1,
  boundaries = 1,
  compact = false,
  ariaLabel = "pagination",
  className,
}: PaginationProps) {
  const total = Math.max(0, Math.floor(pageCount));
  if (total <= 1) return null;

  const current = Math.min(Math.max(1, page), total);
  const items = compact ? [] : paginationRange(current, total, siblings, boundaries);

  const step = (
    direction: -1 | 1,
    Icon: typeof ChevronLeft,
    label: string,
  ) => {
    const target = current + direction;
    const disabled = target < 1 || target > total;
    return (
      <button
        type="button"
        disabled={disabled}
        aria-label={label}
        onClick={() => onChange(target)}
        className={cn(
          "flex size-8 items-center justify-center border border-white/15 transition-colors",
          disabled
            ? "cursor-not-allowed text-white/20"
            : "text-white/60 hover:border-white/35 hover:bg-white/5 hover:text-white",
        )}
      >
        <Icon aria-hidden className="size-4" strokeWidth={1.5} />
      </button>
    );
  };

  return (
    <nav aria-label={ariaLabel} className={cn("flex items-center gap-1", className)}>
      {step(-1, ChevronLeft, "previous page")}

      {compact ? (
        <span className="px-3 font-mono text-[11px] tabular-nums text-white/50">
          {current} / {total}
        </span>
      ) : (
        <ul className="flex items-center gap-1">
          {items.map((item, index) =>
            item === GAP ? (
              <li
                key={`gap-${index}`}
                aria-hidden
                className="flex size-8 items-center justify-center font-mono text-[11px] text-white/25"
              >
                …
              </li>
            ) : (
              <li key={item}>
                <button
                  type="button"
                  aria-current={item === current ? "page" : undefined}
                  aria-label={`page ${item}`}
                  onClick={() => onChange(item)}
                  className={cn(
                    "flex size-8 items-center justify-center border font-mono text-[11px] tabular-nums transition-colors",
                    item === current
                      ? "border-white bg-white text-black"
                      : "border-white/15 text-white/60 hover:border-white/35 hover:bg-white/5 hover:text-white",
                  )}
                >
                  {item}
                </button>
              </li>
            ),
          )}
        </ul>
      )}

      {step(1, ChevronRight, "next page")}
    </nav>
  );
}

/** An ellipsis gap in the page list. */
export const GAP = "gap" as const;

export type PageItem = number | typeof GAP;

/**
 * The page numbers to render, with `GAP` where pages are elided.
 *
 * Split out from the component because this is the part with edge cases worth
 * testing: a run only one page shorter than the gap that would replace it, and
 * a current page close enough to an end that a naively clamped window would
 * shrink.
 */
export function paginationRange(
  page: number,
  pageCount: number,
  siblings = 1,
  boundaries = 1,
): PageItem[] {
  const total = Math.max(0, Math.floor(pageCount));
  if (total <= 0) return [];

  // Everything fits: the two boundary runs, the sibling window either side of
  // the current page, and the two positions an ellipsis could occupy.
  const visible = boundaries * 2 + siblings * 2 + 3;
  if (total <= visible) return Array.from({ length: total }, (_, i) => i + 1);

  const current = Math.min(Math.max(1, page), total);

  // The window keeps a constant width even at the ends: clamping it without
  // shifting would render "1 2 … 20" on page 1 and "1 … 18 19 20" on page 20,
  // so the control would change width as you paged through it.
  const windowSize = siblings * 2 + 1;
  let windowStart = Math.max(boundaries + 1, current - siblings);
  let windowEnd = windowStart + windowSize - 1;
  if (windowEnd > total - boundaries) {
    windowEnd = total - boundaries;
    windowStart = Math.max(boundaries + 1, windowEnd - windowSize + 1);
  }

  const out: PageItem[] = [];
  for (let i = 1; i <= boundaries; i++) out.push(i);

  // A gap standing in for exactly one page is replaced by that page: "1 … 3"
  // costs the same width as "1 2 3" and tells the reader less.
  if (windowStart > boundaries + 2) out.push(GAP);
  else if (windowStart === boundaries + 2) out.push(boundaries + 1);

  for (let i = windowStart; i <= windowEnd; i++) out.push(i);

  if (windowEnd < total - boundaries - 1) out.push(GAP);
  else if (windowEnd === total - boundaries - 1) out.push(total - boundaries);

  for (let i = total - boundaries + 1; i <= total; i++) out.push(i);

  return out;
}
